package cn.mint.tv;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.widget.*;
import java.io.*;
import java.util.*;
import org.json.*;
/** Small native dialogs, no background framework or additional player. */
@androidx.media3.common.util.UnstableApi
final class TvTools {
 final MainActivity a;TvTools(MainActivity a){this.a=a;}
 void show(){new AlertDialog.Builder(a).setTitle("检测、节目单与备份").setItems(new String[]{"隐藏频道管理 / 单频道重检","重新检测所有频道","网络适配","XMLTV 当前 / 下一节目","导出本地备份","从本地备份恢复"},(d,i)->{switch(i){case 0:hidden();break;case 1:new AlertDialog.Builder(a).setTitle("重新检测全部频道？").setMessage("逐一静音试播会消耗带宽。仅检测成功才恢复隐藏频道。").setPositiveButton("开始",(x,w)->a.io.execute(()->Health.ensure(a,true))).setNegativeButton("取消",null).show();break;case 2:a.networkSettings();break;case 3:epg();break;case 4:new AlertDialog.Builder(a).setTitle("导出本地备份").setMessage("包含频道源、订阅地址、收藏、最近观看和节目单地址。订阅地址可能含账号凭据，请妥善保管文件。检测结果按设备网络重新生成。").setPositiveButton("选择保存位置",(x,w)->document(true)).setNegativeButton("取消",null).show();break;case 5:document(false);}}).setNegativeButton("返回",null).show();}
 void document(boolean save){try{Intent in=new Intent(save?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);in.addCategory(Intent.CATEGORY_OPENABLE);in.setType(save?"application/json":"*/*");if(save)in.putExtra(Intent.EXTRA_TITLE,"薄荷电视备份.json");a.startActivityForResult(in,save?22:23);}catch(ActivityNotFoundException e){a.toast("盒子未提供文件选择器，请安装支持系统文档选择的文件管理器");}}
 void hidden(){List<Playlist.Channel> list=new ArrayList<>();for(Playlist.Channel c:a.channels)if(Health.hidden(a,c))list.add(c);if(list.isEmpty()){a.toast("没有隐藏频道；可在播放线路菜单重检当前频道");return;}String[] labels=new String[list.size()];for(int i=0;i<labels.length;i++){Playlist.Channel c=list.get(i);JSONObject r=Health.results(a).optJSONObject(Playlist.key(c.name));labels[i]=c.name+" · "+(r!=null&&r.optBoolean("uncertain")?"检测不确定，保留隐藏":"全部源不可用")+"\n"+(r==null?"":android.text.format.DateFormat.format("MM-dd HH:mm",r.optLong("checkedAt")));}new AlertDialog.Builder(a).setTitle("隐藏频道 · 选择单独重检").setItems(labels,(d,i)->{a.io.execute(()->Health.recheck(a,list.get(i)));a.toast("已加入单频道检测队列；成功后自动显示");}).setNegativeButton("返回",null).show();}
 void epg(){EditText input=new EditText(a);input.setSingleLine(true);input.setInputType(17);input.setHint("XMLTV / XMLTV.gz 的 HTTP(S) 地址");input.setText(Store.prefs(a).getString("epgUrl",""));LinearLayout box=a.col();box.setPadding(a.dp(24),a.dp(12),a.dp(24),0);box.addView(input);TextView status=a.text(Store.prefs(a).getString("epgStatus","仅缓存每频道当前及下一节目；每 6 小时更新，失败保留缓存。"),12,a.MUTED);box.addView(status);new AlertDialog.Builder(a).setTitle("简版节目单（可选）").setView(box).setPositiveButton("保存并更新",(d,w)->{String url=input.getText().toString().trim();try{if(!url.isEmpty())BackupData.http(url);}catch(Exception e){a.toast(e.getMessage());return;}Store.prefs(a).edit().putString("epgUrl",url).putLong("epgTime",0).putString("epgData","{}").apply();a.io.execute(()->{Epg.refresh(a,true);a.handler.post(()->{a.updateEpg();a.toast(Store.prefs(a).getString("epgStatus",url.isEmpty()?"节目单已关闭":""));});});}).setNegativeButton("返回",null).show();}
 void result(int request,Uri uri){a.io.execute(()->{try{if(request==22){LocalState.get().flush();String data=BackupData.export(Store.prefs(a).getAll()).toString();try(OutputStream out=a.getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("无法打开保存位置");out.write(data.getBytes(java.nio.charset.StandardCharsets.UTF_8));}a.handler.post(()->a.toast("备份已导出"));}
 else{String text;try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("无法读取备份");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>32*1024*1024)throw new IOException("备份超过 32 MB");out.write(b,0,n);}text=out.toString("UTF-8");}Map<String,Object> validated=BackupData.validate(text);a.handler.post(()->new AlertDialog.Builder(a).setTitle("恢复已校验的备份？").setMessage("将替换源列表、收藏和设置；当前播放会停止，检测结果重新生成。原有数据仅在新数据完整落盘后替换。").setPositiveButton("恢复",(d,w)->restore(validated)).setNegativeButton("取消",null).show());}}
 catch(Exception e){a.handler.post(()->a.toast("备份操作失败："+e.getMessage()));}});}
 void restore(Map<String,Object> state){a.getSystemService(android.app.job.JobScheduler.class).cancel(Health.JOB);a.generation++;a.cancelTimeout();if(a.player!=null){a.player.stop();a.player.clearMediaItems();}a.current=null;a.io.execute(()->{try{LocalState.get().restore(state);Health.ensure(a,true);a.handler.post(()->{a.favorites=new HashSet<>(Store.prefs(a).getStringSet("favorites",new HashSet<>()));a.numbers=new JSONObject();a.title.setText("请选择频道");a.subtitle.setText("备份已恢复");a.reload();a.updateNetworkLabel();a.updateEpg();a.refresh(false,true);a.toast("备份已恢复，正在后台检测");});}catch(Exception e){a.handler.post(()->a.toast("恢复失败，原数据保留："+e.getMessage()));}});}
}
